import java.util.ArrayList;
import java.util.Scanner;

public class TextDoc {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalLines = scanner.nextInt();
        scanner.nextLine();
        String inputString = scanner.nextLine();
        String[] segments = inputString.split("\\(.*?\\)");
        int maxLen = 0;
        for (String segment : segments) {
            StringTokenizer tokenizer = new StringTokenizer(segment, "_");
            while (tokenizer.hasMoreTokens()) {
                String token = tokenizer.nextToken();
                if (token.length() > maxLen) {
                    maxLen = token.length();
                }
            }
        }
        ArrayList<String> enclosedTexts = new ArrayList<>();
        int startIdx = -1;
        for (int i = 0; i < inputString.length(); i++) {
            if (inputString.charAt(i) == '(') {
                startIdx = i;
            } else if (inputString.charAt(i) == ')' && startIdx != -1) {
                enclosedTexts.add(inputString.substring(startIdx + 1, i));
            }
        }
        int wordCount = 0;
        for (String enclosed : enclosedTexts) {
            String[] words = enclosed.split("_");
            for (String word : words) {
                if (word.length() > 0) {
                    wordCount++;
                }
            }
        }
        System.out.println(maxLen + " " + wordCount);
    }
}
